package main

import (
	"encoding/json"
	"fmt"
	"gio-mw/token"
	"log"
	"os"
	"path"
	"path/filepath"
	"strings"
)

var fileTemplateHeader = `// SPDX-License-Identifier: Unlicense OR MIT
// @file Generated by cmd/genscheme/main.go. DO NOT EDIT!

package schemes

import (
	"encoding/json"
	"fmt"
	"gio-mw/token"
)
`

var functionTemplate = `
func Scheme%s() *token.Scheme {
	rawData := %s
	scheme := token.Scheme{}
	err := json.Unmarshal([]byte(rawData), &scheme)
	if err != nil {
		panic(fmt.Errorf("failed to parse Scheme%s: %%v", err))
	}
	return &scheme
}
`

func main() {
	if len(os.Args) != 2 {
		log.Fatalf("scheme directory path argument required")
	}
	dirPath := os.Args[1]
	dirEntries, err := os.ReadDir(dirPath)
	if err != nil {
		log.Fatalf("ReadDir failed: %v", err)
	}
	for _, dirEntry := range dirEntries {
		extension := filepath.Ext(dirEntry.Name())
		// TODO: Enforce name pattern.
		themeName := strings.TrimSuffix(dirEntry.Name(), extension)
		if extension != ".json" {
			continue
		}
		fontFilePath := path.Join(dirPath, dirEntry.Name())
		log.Printf("processing %v", fontFilePath)
		hexData := readMaterialThemeJson(fontFilePath)
		fileContent := fileTemplateHeader
		fileContent += getFunctionTemplateForScheme(schemeFromHexScheme(hexData.Schemes.Light), themeName+"Light")
		fileContent += getFunctionTemplateForScheme(schemeFromHexScheme(hexData.Schemes.LightMediumContrast), themeName+"LightMediumContrast")
		fileContent += getFunctionTemplateForScheme(schemeFromHexScheme(hexData.Schemes.LightHighContrast), themeName+"LightHighContrast")
		fileContent += getFunctionTemplateForScheme(schemeFromHexScheme(hexData.Schemes.Dark), themeName+"Dark")
		fileContent += getFunctionTemplateForScheme(schemeFromHexScheme(hexData.Schemes.DarkMediumContrast), themeName+"DarkMediumContrast")
		fileContent += getFunctionTemplateForScheme(schemeFromHexScheme(hexData.Schemes.DarkHighContrast), themeName+"DarkHighContrast")
		err = os.WriteFile(path.Join(dirPath, themeName+".go"), []byte(fileContent), 0644)
		if err != nil {
			log.Fatalf("WriteFile failed: %v", err)
		}
	}
}

func getFunctionTemplateForScheme(scheme token.Scheme, schemeName string) string {
	lightSchemeData, err := json.Marshal(scheme)
	if err != nil {
		log.Fatalf("Marshal failed: %v", err)
	}
	return fmt.Sprintf(functionTemplate, schemeName, "`"+string(lightSchemeData)+"`", schemeName)

}

func readMaterialThemeJson(filePath string) HexData {
	content, err := os.ReadFile(filePath)
	if err != nil {
		log.Fatal("error opening file: ", err)
	}

	var hexData HexData
	err = json.Unmarshal(content, &hexData)
	if err != nil {
		log.Fatal("error during JSON unmarshal: ", err)
	}

	return hexData
}

func schemeFromHexScheme(scheme HexScheme) token.Scheme {
	return token.Scheme{
		Primary: token.MatColorSet{
			Color:   token.NewMatColorFromHexString(scheme.Primary),
			OnColor: token.NewMatColorFromHexString(scheme.OnPrimary),
		},
		PrimaryContainer: token.MatColorSet{
			Color:   token.NewMatColorFromHexString(scheme.PrimaryContainer),
			OnColor: token.NewMatColorFromHexString(scheme.OnPrimaryContainer),
		},
		PrimaryFixed: token.MatColorSet{
			Color:   token.NewMatColorFromHexString(scheme.PrimaryFixed),
			OnColor: token.NewMatColorFromHexString(scheme.OnPrimaryFixed),
		},
		PrimaryFixedVariant: token.MatColorSet{
			Color:   token.NewMatColorFromHexString(scheme.PrimaryFixedDim),
			OnColor: token.NewMatColorFromHexString(scheme.OnPrimaryFixedVariant),
		},
		Secondary: token.MatColorSet{
			Color:   token.NewMatColorFromHexString(scheme.Secondary),
			OnColor: token.NewMatColorFromHexString(scheme.OnSecondary),
		},
		SecondaryContainer: token.MatColorSet{
			Color:   token.NewMatColorFromHexString(scheme.SecondaryContainer),
			OnColor: token.NewMatColorFromHexString(scheme.OnSecondaryContainer),
		},
		SecondaryFixed: token.MatColorSet{
			Color:   token.NewMatColorFromHexString(scheme.SecondaryFixed),
			OnColor: token.NewMatColorFromHexString(scheme.OnSecondaryFixed),
		},
		SecondaryFixedVariant: token.MatColorSet{
			Color:   token.NewMatColorFromHexString(scheme.SecondaryFixedDim),
			OnColor: token.NewMatColorFromHexString(scheme.OnSecondaryFixedVariant),
		},
		Tertiary: token.MatColorSet{
			Color:   token.NewMatColorFromHexString(scheme.Tertiary),
			OnColor: token.NewMatColorFromHexString(scheme.OnTertiary),
		},
		TertiaryContainer: token.MatColorSet{
			Color:   token.NewMatColorFromHexString(scheme.TertiaryContainer),
			OnColor: token.NewMatColorFromHexString(scheme.OnTertiaryContainer),
		},
		TertiaryFixed: token.MatColorSet{
			Color:   token.NewMatColorFromHexString(scheme.TertiaryFixed),
			OnColor: token.NewMatColorFromHexString(scheme.OnTertiaryFixed),
		},
		TertiaryFixedVariant: token.MatColorSet{
			Color:   token.NewMatColorFromHexString(scheme.TertiaryFixedDim),
			OnColor: token.NewMatColorFromHexString(scheme.OnTertiaryFixedVariant),
		},
		Surface: token.MatColorSet{
			Color:   token.NewMatColorFromHexString(scheme.Surface),
			OnColor: token.NewMatColorFromHexString(scheme.OnSurface),
		},
		SurfaceVariant: token.MatColorSet{
			Color:   token.NewMatColorFromHexString(scheme.SurfaceVariant),
			OnColor: token.NewMatColorFromHexString(scheme.OnSurfaceVariant),
		},
		SurfaceDim:              token.NewMatColorFromHexString(scheme.SurfaceDim),
		SurfaceBright:           token.NewMatColorFromHexString(scheme.SurfaceBright),
		SurfaceContainerLowest:  token.NewMatColorFromHexString(scheme.SurfaceContainerLowest),
		SurfaceContainerLow:     token.NewMatColorFromHexString(scheme.SurfaceContainerLow),
		SurfaceContainer:        token.NewMatColorFromHexString(scheme.SurfaceContainer),
		SurfaceContainerHigh:    token.NewMatColorFromHexString(scheme.SurfaceContainerHigh),
		SurfaceContainerHighest: token.NewMatColorFromHexString(scheme.SurfaceContainerHighest),
		InverseSurface: token.MatColorSet{
			Color:   token.NewMatColorFromHexString(scheme.InverseSurface),
			OnColor: token.NewMatColorFromHexString(scheme.InverseOnSurface),
		},
		InversePrimary: token.NewMatColorFromHexString(scheme.InversePrimary),
		Background: token.MatColorSet{
			Color:   token.NewMatColorFromHexString(scheme.Background),
			OnColor: token.NewMatColorFromHexString(scheme.OnBackground),
		},
		Outline:        token.NewMatColorFromHexString(scheme.Outline),
		OutlineVariant: token.NewMatColorFromHexString(scheme.OutlineVariant),
		Error: token.MatColorSet{
			Color:   token.NewMatColorFromHexString(scheme.Error),
			OnColor: token.NewMatColorFromHexString(scheme.OnError),
		},
		ErrorContainer: token.MatColorSet{
			Color:   token.NewMatColorFromHexString(scheme.ErrorContainer),
			OnColor: token.NewMatColorFromHexString(scheme.OnErrorContainer),
		},
		Scrim:  token.NewMatColorFromHexString(scheme.Scrim),
		Shadow: token.NewMatColorFromHexString(scheme.Shadow),
	}
}
